layer.css:
[data-ryt="pitch"] { color: rgb(76, 86, 106); border-left: 3px solid rgb(229, 231, 235); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 14px; font-weight: 400; font-style: italic; line-height: 1.7; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(76, 86, 106); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 14px; transition: color 0.2s, background-color 0.2s, border-color 0.2s; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: var(--ryt-text); border-top: 1px solid rgb(229, 231, 235); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-bottom: 1px dotted var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: 0.2s; border-top: none; border-right: none; border-left: none }
[data-ryt="hero"] h1 { color: var(--ryt-text); font-family: "JetBrains Mono", "SF Mono", Consolas, monospace; font-size: 25.2px; font-weight: 700; font-style: normal; line-height: 1.25; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.2s, background-color 0.2s, border-color 0.2s }
[data-ryt="section"] > h2 { color: var(--ryt-text); border-radius: 0px; font-family: "JetBrains Mono", "SF Mono", Consolas, monospace; font-weight: 700; font-style: normal; line-height: 1.3; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.2s, background-color 0.2s, border-color 0.2s }
[data-ryt="review"] { color: #838996; font-family: var(--ryt-font-heading); font-size: 10.92px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(140, 146, 160); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.2s, background-color 0.2s, border-color 0.2s }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: #838996; font-family: var(--ryt-font-heading); font-size: 10.08px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(140, 146, 160); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.2s, background-color 0.2s, border-color 0.2s }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: "JetBrains Mono", "SF Mono", Consolas, monospace; font-size: 18px; font-weight: 600; font-style: normal; line-height: 1; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.2s, background-color 0.2s, border-color 0.2s }
[data-ryt="nav"] a { color: var(--ryt-text); border-radius: 0px; font-family: "IBM Plex Mono", Menlo, Monaco, monospace; font-size: 12.6px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: color 0.2s }
[data-ryt="button"] { color: var(--ryt-text); background-color: rgb(245, 245, 245); border-top: 2px solid rgb(229, 231, 235); border-right: 2px solid rgb(229, 231, 235); border-bottom: 2px solid rgb(229, 231, 235); border-left: 2px solid rgb(229, 231, 235); border-radius: 50%; box-shadow: rgba(0, 0, 0, 0.15) 0px 2px 8px 0px; font-family: Arial; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: 0.2s }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.15s }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 12.32px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.2s, background-color 0.2s, border-color 0.2s }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: #5e81ac; border-bottom-width: medium; border-bottom-style: none; border-bottom-color: currentcolor }
[data-ryt="button"]:hover { background-color: #5e81ac }
[data-ryt="nav"] a:hover { color: #5e81ac }
